INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000820000','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000820000","revision":1,"targetId":"80000000-0000-4000-8000-000000008200","prompt":"Die Kinder ___ mit voller Geschwindigkeit zur Ziellinie.","instruction":{"en":"Choose the verb or verb form that best completes the German sentence.","de":"Wähle das Verb oder die Verbform, die den deutschen Satz am besten ergänzt."},"hint":{"en":"They are moving at high speed toward the finish.","de":"Sie bewegen sich mit hoher Geschwindigkeit zum Ziel."},"slots":[{"id":"verb","label":"Verb oder Verbform","options":[{"id":"0","text":"schleichen"},{"id":"1","text":"rennen"},{"id":"2","text":"stehen"},{"id":"3","text":"kriechen"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"verb","optionId":"1"}]}],"explanation":{"en":"rennen means run quickly. They are moving at high speed toward the finish.","de":"rennen bedeutet schnell laufen. Sie bewegen sich mit hoher Geschwindigkeit zum Ziel."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Kinder rennen mit voller Geschwindigkeit zur Ziellinie.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical/grammar facts from pinned apps/web/data/pos/verbs.jsonl:L665 (97a062b0e790e7a8307ede869ce51c32b87eb04a6c1a3a87fbec5ca72e6feca5), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
