INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000830061','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000830061","revision":1,"targetId":"80000000-0000-4000-8000-000000008306","prompt":"Obwohl er krankgeschrieben war, erhielt er seinen Lohn weiter. Das nennt man ___.","instruction":{"en":"Choose the noun that best completes the German sentence.","de":"Wähle das Nomen, das den deutschen Satz am besten ergänzt."},"hint":{"en":"The employer continues paying wages during sickness.","de":"Der Lohn wird während der Krankheit weitergezahlt."},"options":[{"id":"0","text":"Entgeltfortzahlung"},{"id":"1","text":"Gehaltskürzung"},{"id":"2","text":"Arbeitszeitverkürzung"},{"id":"3","text":"Kündigungsfrist"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"Entgeltfortzahlung means continued wage payment during certain absences. The employer continues paying wages during sickness.","de":"Entgeltfortzahlung bedeutet Weiterzahlung des Arbeitsentgelts bei bestimmter Abwesenheit. Der Lohn wird während der Krankheit weitergezahlt."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Obwohl er krankgeschrieben war, erhielt er seinen Lohn weiter. Das nennt man Entgeltfortzahlung.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical/grammar facts from pinned apps/web/data/pos/nouns.jsonl:L653 (ea68bec3e34a3121f59b525e2ad83f9e74dcecd401d8d54fa52706136530bb21), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
