INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000840000','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000840000","revision":1,"targetId":"80000000-0000-4000-8000-000000008400","prompt":"Als der Lehrer eine Antwort erwartete, ___ die ganze Klasse; niemand sagte ein Wort.","instruction":{"en":"Choose the verb or verb form that best completes the German sentence.","de":"Wähle das Verb oder die Verbform, die den deutschen Satz am besten ergänzt."},"hint":{"en":"Nobody spoke in response.","de":"Niemand sagte etwas als Antwort."},"slots":[{"id":"verb","label":"Verb oder Verbform","options":[{"id":"0","text":"lachte"},{"id":"1","text":"antwortete"},{"id":"2","text":"schwieg"},{"id":"3","text":"rief"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"verb","optionId":"2"}]}],"explanation":{"en":"schweigen means remain silent. Nobody spoke in response.","de":"schweigen bedeutet nichts sagen. Niemand sagte etwas als Antwort."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Als der Lehrer eine Antwort erwartete, schwieg die ganze Klasse; niemand sagte ein Wort.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical/grammar facts from pinned apps/web/data/pos/verbs.jsonl:L702 (d6cf82ec82cb05ff2f43f76425c167ff4efe541131140d99d1753193a179c343), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
