INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000900000','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000900000","revision":1,"targetId":"80000000-0000-4000-8000-000000009000","prompt":"Auf dem unebenen Gehweg musste sie aufpassen, nicht zu ___.","instruction":{"en":"Choose the expression or verb form that best completes the German sentence.","de":"Wähle den Ausdruck oder die Verbform, die den deutschen Satz am besten ergänzt."},"hint":{"en":"The uneven ground could make her trip.","de":"Der unebene Boden könnte sie ins Straucheln bringen."},"slots":[{"id":"expression","label":"Ausdruck oder Verbform","options":[{"id":"0","text":"schwimmen"},{"id":"1","text":"stolpern"},{"id":"2","text":"fliegen"},{"id":"3","text":"sitzen"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"expression","optionId":"1"}]}],"explanation":{"en":"stolpern means trip or stumble. The uneven ground could make her trip.","de":"stolpern bedeutet beim Gehen ins Straucheln geraten. Der unebene Boden könnte sie ins Straucheln bringen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Auf dem unebenen Gehweg musste sie aufpassen, nicht zu stolpern.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical/grammar facts from pinned apps/web/data/pos/verbs.jsonl:L777 (044e6f27464442df9e4f9fe103bb2c186a71b5971c7ecb1f04686f5416c6deeb), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
