INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000900140','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000900140","revision":1,"targetId":"80000000-0000-4000-8000-000000009014","prompt":"Für das Recycling müssen wir Papier und Glas ___.","instruction":{"en":"Choose the expression or verb form that best completes the German sentence.","de":"Wähle den Ausdruck oder die Verbform, die den deutschen Satz am besten ergänzt."},"hint":{"en":"Different materials should be sorted separately.","de":"Verschiedene Materialien werden getrennt gesammelt."},"slots":[{"id":"expression","label":"Ausdruck oder Verbform","options":[{"id":"0","text":"mischen"},{"id":"1","text":"trennen"},{"id":"2","text":"verbrennen"},{"id":"3","text":"verstecken"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"expression","optionId":"1"}]}],"explanation":{"en":"trennen means separate things. Different materials should be sorted separately.","de":"trennen bedeutet Dinge voneinander unterscheiden oder teilen. Verschiedene Materialien werden getrennt gesammelt."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Für das Recycling müssen wir Papier und Glas trennen.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical/grammar facts from pinned apps/web/data/pos/verbs.jsonl:L805 (d7ed69a92d8486cf428c631c5d5cf6acf979a0aa24ec60d2422c02d6f63fb468), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
