INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000980100','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000980100","revision":1,"targetId":"80000000-0000-4000-8000-000000009810","prompt":"Da niemand ans Telefon geht, ___ ich, dass das Büro schon geschlossen ist.","instruction":{"en":"Choose the verb or verb form that best completes the German sentence.","de":"Wähle das Verb oder die Verbform, die den deutschen Satz sinnvoll ergänzt."},"hint":{"en":"The speaker draws an uncertain conclusion from the unanswered call.","de":"Die Person schließt aus dem Anruf auf etwas, weiß es aber nicht sicher."},"slots":[{"id":"verb","label":"Verb oder Verbform","options":[{"id":"0","text":"verlange"},{"id":"1","text":"veröffentliche"},{"id":"2","text":"vermute"},{"id":"3","text":"verschicke"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"verb","optionId":"2"}]}],"explanation":{"en":"vermuten means suspect or suppose without proof in this context; the required form is \"vermute\".","de":"vermuten bedeutet hier: etwas ohne Gewissheit vermuten. Die passende Form lautet „vermute“."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Da niemand ans Telefon geht, vermute ich, dass das Büro schon geschlossen ist.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on pinned lexical and grammar facts from apps/web/data/pos/verbs.jsonl:L904 (7570d0a13c0fee56b9571068c3e1280b7538f3390993248f72cc214b2b407e43), 2026-10-29. No inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
