INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001190000','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001190000","revision":1,"targetId":"80000000-0000-4000-8000-000000011900","prompt":"Wenn zwei Kollegen sich nicht einigen können, sieht die Betriebsvereinbarung vor, im ___ eine neutrale Person einzuschalten.","instruction":{"en":"Choose the noun or noun form that best completes the German sentence.","de":"Wähle das Nomen oder die Nomenform, die den deutschen Satz sinnvoll ergänzt."},"hint":{"en":"A disagreement triggers the mediation rule.","de":"Ein Streit zwischen Kollegen löst das Verfahren aus."},"slots":[{"id":"noun","label":"Nomen oder Form","options":[{"id":"0","text":"Krankheitsfall"},{"id":"1","text":"Konfliktfall"},{"id":"2","text":"Urlaubsfall"},{"id":"3","text":"Schadensfall"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"1"}]}],"explanation":{"en":"Konfliktfall refers to the event of a dispute.","de":"Konfliktfall bezeichnet das Auftreten eines Streits."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Wenn zwei Kollegen sich nicht einigen können, sieht die Betriebsvereinbarung vor, im Konfliktfall eine neutrale Person einzuschalten.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L1303 (e5fb67c9549566e23bd91cc16a0e6e2c783fcf5e155d12211523dfbfa39fd1a9), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
