INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001230010','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001230010","revision":1,"targetId":"80000000-0000-4000-8000-000000012301","prompt":"Weil der Zug stundenlang stillstand und niemand etwas zu tun hatte, breitete sich ___ aus.","instruction":{"en":"Choose the noun or noun form that makes the sentence correct in context.","de":"Wähle das Nomen oder die Nomenform, die den Satz im Kontext richtig ergänzt."},"hint":{"en":"People have nothing interesting to do.","de":"Niemand ist beschäftigt, und die Zeit vergeht langsam."},"slots":[{"id":"noun","label":"Nomen oder Form","options":[{"id":"0","text":"Vorfreude"},{"id":"1","text":"Erleichterung"},{"id":"2","text":"Begeisterung"},{"id":"3","text":"Langeweile"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"3"}]}],"explanation":{"en":"Langeweile is the feeling of being bored.","de":"Langeweile entsteht, wenn man nichts Interessantes zu tun hat."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Weil der Zug stundenlang stillstand und niemand etwas zu tun hatte, breitete sich Langeweile aus.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on pinned lexical facts apps/web/data/pos/nouns.jsonl:L1410 (8dd81b407663acce74660fd7edc036315d110cad020a47a869bc20668ae8ff83), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
