INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001260090','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001260090","revision":1,"targetId":"80000000-0000-4000-8000-000000012609","prompt":"Nach der Bauabnahme verlangt der Auftraggeber die ___ der festgestellten Schäden.","instruction":{"en":"Choose the expression that correctly completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz richtig ergänzt."},"hint":{"en":"The faults need to be repaired.","de":"Die festgestellten Fehler müssen behoben werden."},"slots":[{"id":"noun","label":"Nomen oder Ausdruck","options":[{"id":"0","text":"Mängelbeseitigung"},{"id":"1","text":"Preiserhöhung"},{"id":"2","text":"Neuvermietung"},{"id":"3","text":"Terminabsage"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"0"}]}],"explanation":{"en":"Mängelbeseitigung means correcting defects.","de":"Mängelbeseitigung ist die Behebung festgestellter Fehler."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Nach der Bauabnahme verlangt der Auftraggeber die Mängelbeseitigung der festgestellten Schäden.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 draft based on pinned lexical facts apps/web/data/pos/nouns.jsonl:L1499 (1fb6a337d26947e3493111ea429bccb48269a4179b364260eaeb99227278bc13), 2026-10-29; no inherited examples reused. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
