INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001260110','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001260110","revision":1,"targetId":"80000000-0000-4000-8000-000000012611","prompt":"Vor dem Einschlafen hören die Kinder ein ___ von einem verzauberten Schloss.","instruction":{"en":"Choose the expression that correctly completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz richtig ergänzt."},"hint":{"en":"The story has magical elements.","de":"Die Geschichte enthält etwas Zauberhaftes."},"slots":[{"id":"noun","label":"Nomen oder Ausdruck","options":[{"id":"0","text":"Märchen"},{"id":"1","text":"Protokoll"},{"id":"2","text":"Fahrplan"},{"id":"3","text":"Gutachten"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"0"}]}],"explanation":{"en":"Märchen is a fairy tale.","de":"Ein Märchen ist eine fantastische Erzählung."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Vor dem Einschlafen hören die Kinder ein Märchen von einem verzauberten Schloss.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 draft based on pinned lexical facts apps/web/data/pos/nouns.jsonl:L1504 (8e50111d6b32e79bb5320581f18cacc2388ccab05b454f93653fb977b9ac8b75), 2026-10-29; no inherited examples reused. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
