INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001260111','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001260111","revision":1,"targetId":"80000000-0000-4000-8000-000000012611","prompt":"Im Märchen kann ein Tier plötzlich sprechen. Was für eine Textsorte ist gemeint?","instruction":{"en":"Read the German context and choose the one accurate interpretation.","de":"Lies den deutschen Kontext und wähle die einzige zutreffende Bedeutung."},"hint":{"en":"Talking animals belong to an imaginative narrative.","de":"Sprechende Tiere gehören zu erfundenen Geschichten."},"options":[{"id":"0","text":"Eine fantastische Erzählung"},{"id":"1","text":"Ein amtliches Prüfprotokoll"},{"id":"2","text":"Eine technische Anleitung"},{"id":"3","text":"Eine wissenschaftliche Messreihe"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"The text is a fairy tale.","de":"Gemeint ist eine fantastische, meist erfundene Geschichte."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"In einem Märchen können Tiere sprechen und andere wunderbare Dinge geschehen.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 draft based on pinned lexical facts apps/web/data/pos/nouns.jsonl:L1504 (8e50111d6b32e79bb5320581f18cacc2388ccab05b454f93653fb977b9ac8b75), 2026-10-29; no inherited examples reused. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
