INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001260140','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001260140","revision":1,"targetId":"80000000-0000-4000-8000-000000012614","prompt":"Die Firma lässt ihre neue ___ schützen, damit Wettbewerber den Namen nicht einfach übernehmen.","instruction":{"en":"Choose the expression that correctly completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz richtig ergänzt."},"hint":{"en":"The company wants to protect its product identity.","de":"Das Unternehmen schützt die Kennzeichnung seiner Produkte."},"slots":[{"id":"noun","label":"Nomen oder Ausdruck","options":[{"id":"0","text":"Marke"},{"id":"1","text":"Schicht"},{"id":"2","text":"Lieferung"},{"id":"3","text":"Abteilung"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"0"}]}],"explanation":{"en":"Marke means brand or trademark here.","de":"Eine Marke kennzeichnet Produkte oder Dienstleistungen eines Unternehmens."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Firma lässt ihre neue Marke schützen, damit Wettbewerber den Namen nicht einfach übernehmen.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 draft based on pinned lexical facts apps/web/data/pos/nouns.jsonl:L1507 (ef4dd0f81d48c05a06a6dc6e0dd9258b8d0694098c25069d850f1e1bc362a46f), 2026-10-29; no inherited examples reused. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
