INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001260181','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001260181","revision":1,"targetId":"80000000-0000-4000-8000-000000012618","prompt":"Nach dem Maschinenbaustudium entwickelt sie Antriebe für Industrieanlagen. In welchem Fachgebiet arbeitet sie?","instruction":{"en":"Read the German context and choose the one accurate interpretation.","de":"Lies den deutschen Kontext und wähle die einzige zutreffende Bedeutung."},"hint":{"en":"The job involves engineering industrial drives.","de":"Die Person entwickelt technische Antriebe."},"options":[{"id":"0","text":"In der Entwicklung von Maschinen und technischen Anlagen"},{"id":"1","text":"In der Erforschung alter Sprachen"},{"id":"2","text":"In der Gestaltung von Werbeplakaten"},{"id":"3","text":"In der Betreuung von Vorschulkindern"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"She works in mechanical engineering.","de":"Sie arbeitet im Maschinenbau und entwickelt technische Anlagen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Sie entwickelt als Maschinenbauingenieurin Antriebe für Industrieanlagen.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 draft based on pinned lexical facts apps/web/data/pos/nouns.jsonl:L1514 (f84dfbc4e34fc80f17c9a0b5770add3caca9756d485833a6785b99fab8b4bfda), 2026-10-29; no inherited examples reused. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
