INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001270001','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001270001","revision":1,"targetId":"80000000-0000-4000-8000-000000012700","prompt":"Die Maßnahme sieht vor, dass alle Beschäftigten eine Sicherheitsschulung besuchen. Was bedeutet „Maßnahme“ hier?","instruction":{"en":"Read the German context and choose the one accurate interpretation.","de":"Lies den deutschen Kontext und wähle die einzige zutreffende Bedeutung."},"hint":{"en":"The training is intended to achieve a safety goal.","de":"Die Schulung soll ein konkretes Ziel erreichen."},"options":[{"id":"0","text":"Eine gezielte Handlung zur Verbesserung der Sicherheit"},{"id":"1","text":"Eine regelmäßige Auszahlung des Gehalts"},{"id":"2","text":"Eine Liste der bestellten Waren"},{"id":"3","text":"Eine Änderung der Firmenadresse"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"It is a targeted safety intervention.","de":"Es handelt sich um eine gezielte Sicherheitsmaßnahme."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der Betrieb führt als Maßnahme eine Sicherheitsschulung ein.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L1516 (34a5c3fb74d1855225f24a776e8377f81d3c6cc2e891a73adcdbbf2500bce070), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
