INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001270130','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001270130","revision":1,"targetId":"80000000-0000-4000-8000-000000012713","prompt":"Von 40 Mitgliedern stimmten 31 dafür; damit unterstützte die ___ den Vorschlag.","instruction":{"en":"Choose the expression that correctly completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz richtig ergänzt."},"hint":{"en":"Thirty-one of forty is more than half.","de":"31 von 40 sind mehr als die Hälfte."},"slots":[{"id":"noun","label":"Nomen oder Ausdruck","options":[{"id":"0","text":"Mehrheit"},{"id":"1","text":"Minderheit"},{"id":"2","text":"Geschäftsführung"},{"id":"3","text":"Abteilung"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"0"}]}],"explanation":{"en":"Mehrheit means more than half in this vote.","de":"Die Mehrheit ist der größere Teil einer Gruppe."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Von 40 Mitgliedern stimmten 31 dafür; damit unterstützte die Mehrheit den Vorschlag.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L1531 (aca2ee11294f0ee34b3c7d67f67618a2df16c68f3aa58cdb7a61582414996df6), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
