INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001270131','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001270131","revision":1,"targetId":"80000000-0000-4000-8000-000000012713","prompt":"Eine Mehrheit von 60 Prozent der Befragten unterstützt den Plan. Was bedeutet das?","instruction":{"en":"Read the German context and choose the one accurate interpretation.","de":"Lies den deutschen Kontext und wähle die einzige zutreffende Bedeutung."},"hint":{"en":"Compare sixty percent with fifty percent.","de":"Vergleiche 60 Prozent mit der Hälfte."},"options":[{"id":"0","text":"Mehr als die Hälfte ist dafür."},{"id":"1","text":"Genau die Hälfte ist dagegen."},{"id":"2","text":"Weniger als ein Drittel ist dafür."},{"id":"3","text":"Niemand hat abgestimmt."}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"Sixty percent is a majority.","de":"60 Prozent sind mehr als die Hälfte."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Mehr als die Hälfte der Befragten unterstützt den Plan.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L1531 (aca2ee11294f0ee34b3c7d67f67618a2df16c68f3aa58cdb7a61582414996df6), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
