INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001270181','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001270181","revision":1,"targetId":"80000000-0000-4000-8000-000000012718","prompt":"Die Mensa der Hochschule bietet heute auch vegetarische Gerichte an. Was ist eine Mensa?","instruction":{"en":"Read the German context and choose the one accurate interpretation.","de":"Lies den deutschen Kontext und wähle die einzige zutreffende Bedeutung."},"hint":{"en":"Meals are served there on campus.","de":"Dort bekommt man auf dem Campus Essen."},"options":[{"id":"0","text":"Ein Speisesaal für Studierende und Beschäftigte"},{"id":"1","text":"Ein Labor für chemische Experimente"},{"id":"2","text":"Ein Büro für Prüfungsanmeldungen"},{"id":"3","text":"Ein Raum für Sportveranstaltungen"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"Mensa refers to the university dining hall.","de":"Eine Mensa bietet Essen an einer Hochschule an."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"In der Hochschulmensa können Studierende und Beschäftigte essen.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L1538 (f7080228fdbc8989003243c27b48be32df0d13ddb85896471be57eb7e9ac3b38), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
