INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001280160','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001280160","revision":1,"targetId":"80000000-0000-4000-8000-000000012816","prompt":"Von 50 Mitgliedern stimmten nur neun dagegen; die ___ lehnte den Vorschlag ab.","instruction":{"en":"Choose the expression that correctly completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz richtig ergänzt."},"hint":{"en":"Nine out of fifty is the smaller group.","de":"Neun von fünfzig sind deutlich weniger als die Hälfte."},"slots":[{"id":"noun","label":"Nomen oder Ausdruck","options":[{"id":"0","text":"Minderheit"},{"id":"1","text":"Mehrheit"},{"id":"2","text":"Geschäftsführung"},{"id":"3","text":"Abteilung"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"0"}]}],"explanation":{"en":"Minderheit is the smaller group here.","de":"Die Minderheit ist hier der kleinere Teil der Abstimmenden."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Von 50 Mitgliedern stimmten nur neun dagegen; die Minderheit lehnte den Vorschlag ab.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L1564 (1d3951ab9c80a47c5e1d37362a3809bf2c11915c3da2051ff624da2b39a8d0c5), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
