INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001280161','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001280161","revision":1,"targetId":"80000000-0000-4000-8000-000000012816","prompt":"Eine Minderheit von zehn Prozent sprach sich gegen den Plan aus. Wie viele waren dagegen?","instruction":{"en":"Read the German context and choose the one accurate interpretation.","de":"Lies den deutschen Kontext und wähle die einzige zutreffende Bedeutung."},"hint":{"en":"Compare ten percent with fifty percent.","de":"Vergleiche zehn Prozent mit der Hälfte."},"options":[{"id":"0","text":"Weniger als die Hälfte"},{"id":"1","text":"Genau die Hälfte"},{"id":"2","text":"Alle Befragten"},{"id":"3","text":"Mehr als drei Viertel"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"Ten percent is a minority.","de":"Zehn Prozent sind weniger als die Hälfte."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Nur ein kleiner Teil der Befragten war gegen den Plan.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L1564 (1d3951ab9c80a47c5e1d37362a3809bf2c11915c3da2051ff624da2b39a8d0c5), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
