INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001280170','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001280170","revision":1,"targetId":"80000000-0000-4000-8000-000000012817","prompt":"Der gesetzliche ___ legt eine Untergrenze für den Stundenlohn fest.","instruction":{"en":"Choose the expression that correctly completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz richtig ergänzt."},"hint":{"en":"It is a legally set wage floor.","de":"Es geht um eine gesetzliche Untergrenze beim Lohn."},"slots":[{"id":"noun","label":"Nomen oder Ausdruck","options":[{"id":"0","text":"Mindestlohn"},{"id":"1","text":"Mietpreis"},{"id":"2","text":"Umsatz"},{"id":"3","text":"Kaufpreis"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"0"}]}],"explanation":{"en":"Mindestlohn is the minimum legal wage.","de":"Der Mindestlohn legt eine gesetzliche Lohnuntergrenze fest."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der gesetzliche Mindestlohn legt eine Untergrenze für den Stundenlohn fest.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L1565 (e8fe663a0454a4340b6a80e869b9570f17858904c71276b120d69d1db7cc80e1), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
