INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001290030','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001290030","revision":1,"targetId":"80000000-0000-4000-8000-000000012903","prompt":"Der Betriebsrat setzt sich für mehr ___ bei Entscheidungen über Arbeitsbedingungen ein.","instruction":{"en":"Choose the expression that correctly completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz richtig ergänzt."},"hint":{"en":"Employees want a voice in workplace decisions.","de":"Beschäftigte möchten an Entscheidungen beteiligt werden."},"slots":[{"id":"noun","label":"Nomen oder Ausdruck","options":[{"id":"0","text":"Mitbestimmung"},{"id":"1","text":"Werbung"},{"id":"2","text":"Lagerhaltung"},{"id":"3","text":"Kundenbindung"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"0"}]}],"explanation":{"en":"Mitbestimmung is participation in decision-making.","de":"Mitbestimmung bedeutet Beteiligung an bestimmten Entscheidungen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der Betriebsrat setzt sich für mehr Mitbestimmung bei Entscheidungen über Arbeitsbedingungen ein.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L1574 (0256641ee6a2f65a968007f8112035d26b5b9fb3d2bef9e976ed62735b529065), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
