INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001290140','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001290140","revision":1,"targetId":"80000000-0000-4000-8000-000000012914","prompt":"Neue barrierefreie Busse verbessern die ___ von Menschen mit eingeschränkter Bewegungsfreiheit.","instruction":{"en":"Choose the expression that correctly completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz richtig ergänzt."},"hint":{"en":"Accessible transport makes it easier to get around.","de":"Barrierefreie Busse erleichtern die Fortbewegung."},"slots":[{"id":"noun","label":"Nomen oder Ausdruck","options":[{"id":"0","text":"Mobilität"},{"id":"1","text":"Buchhaltung"},{"id":"2","text":"Versicherung"},{"id":"3","text":"Arbeitszeit"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"0"}]}],"explanation":{"en":"Mobilität is the ability to move about.","de":"Mobilität bezeichnet die Möglichkeit, sich fortzubewegen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Neue barrierefreie Busse verbessern die Mobilität von Menschen mit eingeschränkter Bewegungsfreiheit.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L1591 (0a0aedbee583c3cfa08e1ef96cac57880885a2b2394142221742c13dcd47a16e), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
