INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001340180','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001340180","revision":1,"targetId":"80000000-0000-4000-8000-000000013418","prompt":"Während der ___ breitete sich die ansteckende Krankheit über viele Länder aus.","instruction":{"en":"Choose the expression that correctly completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz richtig ergänzt."},"hint":{"en":"The infectious disease spread internationally.","de":"Die Krankheit verbreitete sich über Ländergrenzen hinweg."},"slots":[{"id":"noun","label":"Nomen oder Ausdruck","options":[{"id":"0","text":"Pandemie"},{"id":"1","text":"Inventur"},{"id":"2","text":"Messe"},{"id":"3","text":"Bewerbung"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"0"}]}],"explanation":{"en":"Pandemie means a widespread infectious-disease outbreak.","de":"Eine Pandemie ist die weite, länderübergreifende Ausbreitung einer Infektionskrankheit."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Während der Pandemie breitete sich die ansteckende Krankheit über viele Länder aus.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L1734 (0fa2ec219e804a1e445a48c49e3c93cbfe0adcdcd97deab5d1e0e3d7eb0a639c), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
