INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001340181','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001340181","revision":1,"targetId":"80000000-0000-4000-8000-000000013418","prompt":"Eine Pandemie kann viele Länder gleichzeitig betreffen. Was kennzeichnet sie?","instruction":{"en":"Read the German context and choose the one accurate interpretation.","de":"Lies den deutschen Kontext und wähle die einzige zutreffende Bedeutung."},"hint":{"en":"The disease crosses borders.","de":"Die Krankheit breitet sich über große Gebiete aus."},"options":[{"id":"0","text":"Eine weitreichende Ausbreitung einer Infektionskrankheit"},{"id":"1","text":"Eine einzelne kleine Firmenfeier"},{"id":"2","text":"Eine technische Panne in einem Gebäude"},{"id":"3","text":"Eine normale saisonale Inventur"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"It is an internationally widespread outbreak.","de":"Eine Pandemie betrifft eine großräumige Ausbreitung einer Infektionskrankheit."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Infektionskrankheit breitet sich über viele Länder aus.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L1734 (0fa2ec219e804a1e445a48c49e3c93cbfe0adcdcd97deab5d1e0e3d7eb0a639c), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
