INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001380171','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001380171","revision":1,"targetId":"80000000-0000-4000-8000-000000013817","prompt":"Das Team behebt zuerst einen sicherheitskritischen Fehler; das neue Logo kann warten. Welche Aufgabe hat Priorität?","instruction":{"en":"Read the German situation and choose the one correct answer.","de":"Lies die deutsche Situation und wähle die einzige richtige Antwort."},"hint":{"en":"Look at what must be addressed first for safety.","de":"Achte darauf, was aus Sicherheitsgründen zuerst erledigt werden muss."},"options":[{"id":"0","text":"die Auswahl des Logos"},{"id":"1","text":"die Bürodekoration"},{"id":"2","text":"die Behebung des Fehlers"},{"id":"3","text":"die Planung der Feier"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"The safety-critical fix has priority over optional design work.","de":"Die Behebung des sicherheitskritischen Fehlers hat Vorrang."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Behebung des Fehlers hat Priorität.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L1840 (9752daa98fc6e5bce6c7e7857a69901a6ff787472de02afa905c16825dab0111), 2026-10-29. Inherited example sentences not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
