INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001380180','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001380180","revision":1,"targetId":"80000000-0000-4000-8000-000000013818","prompt":"Bevor sie das gebrauchte Auto kaufte, vereinbarte sie beim Händler eine ___.","instruction":{"en":"Choose the expression that best completes the sentence.","de":"Wähle den Ausdruck, der den Satz am besten ergänzt."},"hint":{"en":"She wants to try driving the vehicle before deciding.","de":"Sie möchte das Auto vor dem Kauf selbst fahren."},"slots":[{"id":"answer","label":"Ausdruck","options":[{"id":"0","text":"Fahrprüfung"},{"id":"1","text":"Reparatur"},{"id":"2","text":"Anmeldung"},{"id":"3","text":"Probefahrt"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"answer","optionId":"3"}]}],"explanation":{"en":"A Probefahrt lets a prospective buyer try a vehicle.","de":"Bei einer Probefahrt testet man ein Fahrzeug vor dem Kauf."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Bevor sie das gebrauchte Auto kaufte, vereinbarte sie beim Händler eine Probefahrt.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L1841 (9b91cf4bcf919398e99f8efb5b5537f4684c8ade92200bf0a8b6d903a9923985), 2026-10-29. Inherited example sentences not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
