INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001440120','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001440120","revision":1,"targetId":"80000000-0000-4000-8000-000000014412","prompt":"Die Gründerin investiert trotz unsicherer Aussichten; ihre ___ ist hoch.","instruction":{"en":"Choose the word that correctly completes the German sentence.","de":"Wähle das Wort, das den deutschen Satz richtig ergänzt."},"hint":{"en":"She accepts uncertainty in pursuit of a goal.","de":"Sie akzeptiert Unsicherheit, um ein Ziel zu erreichen."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"Pünktlichkeit"},{"id":"1","text":"Sprachkenntnis"},{"id":"2","text":"Geduld"},{"id":"3","text":"Risikobereitschaft"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"3"}]}],"explanation":{"en":"Risikobereitschaft is willingness to take risks.","de":"Risikobereitschaft bedeutet, Risiken bewusst einzugehen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Gründerin investiert trotz unsicherer Aussichten; ihre Risikobereitschaft ist hoch.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L1990 (9d1f671cdb24be1b3a100d98a82dc9bde933497a117984add091560ea87512a1), 2026-10-29; inherited example not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
