INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001440121','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001440121","revision":1,"targetId":"80000000-0000-4000-8000-000000014412","prompt":"Eine Person akzeptiert für eine mögliche Chance bewusst einen unsicheren Ausgang. Welche Eigenschaft zeigt sie?","instruction":{"en":"Read the German situation and choose the one correct answer.","de":"Lies die deutsche Situation und wähle die einzige richtige Antwort."},"hint":{"en":"She is willing to face possible losses.","de":"Sie ist bereit, mögliche Verluste in Kauf zu nehmen."},"options":[{"id":"0","text":"Sparsamkeit"},{"id":"1","text":"Risikobereitschaft"},{"id":"2","text":"Zurückhaltung"},{"id":"3","text":"Gleichgültigkeit"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"This shows Risikobereitschaft.","de":"Das zeigt Risikobereitschaft."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Person zeigt Risikobereitschaft.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L1990 (9d1f671cdb24be1b3a100d98a82dc9bde933497a117984add091560ea87512a1), 2026-10-29; inherited example not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
