INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001510000','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001510000","revision":1,"targetId":"80000000-0000-4000-8000-000000015100","prompt":"Für die Abfahrt kaufte sie zwei lange ___, die an den Skischuhen befestigt werden.","instruction":{"en":"Choose the word that correctly completes the German sentence.","de":"Wähle das Wort, das den deutschen Satz richtig ergänzt."},"hint":{"en":"Each of the two long pieces attaches to a ski boot.","de":"Die beiden langen Geräte werden an Skischuhen befestigt."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"Helme"},{"id":"1","text":"Ski"},{"id":"2","text":"Schals"},{"id":"3","text":"Schlitten"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"1"}]}],"explanation":{"en":"Two skis attach to the boots for sliding downhill.","de":"Zwei Ski werden an den Skischuhen befestigt, um den Hang hinabzugleiten."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Für die Abfahrt kaufte sie zwei lange Ski, die an den Skischuhen befestigt werden.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L2159 (21b4a21d3b6dbb48f53193a74153b8a201c773e4cfbed592e4c69f76180a86f8), 2026-10-29; inherited example not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
