INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001510070','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001510070","revision":1,"targetId":"80000000-0000-4000-8000-000000015107","prompt":"Als die Sonne hinter dem Horizont verschwand, fotografierten wir den ___.","instruction":{"en":"Choose the word that correctly completes the German sentence.","de":"Wähle das Wort, das den deutschen Satz richtig ergänzt."},"hint":{"en":"The event occurs in the evening as daylight fades.","de":"Das Ereignis findet am Abend statt, wenn es dunkler wird."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"Sonnenaufgang"},{"id":"1","text":"Schneefall"},{"id":"2","text":"Sonnenuntergang"},{"id":"3","text":"Regenbogen"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"2"}]}],"explanation":{"en":"The sun disappearing below the horizon is sunset.","de":"Wenn die Sonne unter dem Horizont verschwindet, ist das Sonnenuntergang."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Als die Sonne hinter dem Horizont verschwand, fotografierten wir den Sonnenuntergang.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L2171 (3c3b13c2867eb4e199e675a31fabeb8debbd796175f4bdf7a2c25f1eb8a1b76e), 2026-10-29; inherited example not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
