INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001540031','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001540031","revision":1,"targetId":"80000000-0000-4000-8000-000000015403","prompt":"Eine Person kauft ein Luxusauto vor allem, um ihren Wohlstand zu zeigen. Welche Rolle spielt das Auto für sie?","instruction":{"en":"Read the German situation and choose the one correct answer.","de":"Lies die deutsche Situation und wähle die einzige richtige Antwort."},"hint":{"en":"The intended message to others matters more than transportation.","de":"Wichtiger als die Fortbewegung ist die Wirkung auf andere."},"options":[{"id":"0","text":"Es ist ein öffentliches Verkehrsmittel."},{"id":"1","text":"Es ist eine Lohnabrechnung."},{"id":"2","text":"Es ist ein Haushaltsgerät."},{"id":"3","text":"Es ist ein Statussymbol."}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"3"}],"explanation":{"en":"Here the car represents social prestige.","de":"Hier steht das Auto für gesellschaftliches Ansehen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Das Auto dient ihr als Statussymbol.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L2241 (7cb2a8b644b104e98dd4c86add0a8321103c8ad2d6dbcfa0f758ff9a3501c117), 2026-10-29; inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
