INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001750140','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001750140","revision":1,"targetId":"80000000-0000-4000-8000-000000017514","prompt":"Nach dem Umzug nach Deutschland lernt Elena im Alltag Deutsch neben ihrer Erstsprache. Deutsch ist ihre ___.","instruction":{"en":"Choose the option that completes the German sentence correctly.","de":"Wähle die Option, die den deutschen Satz richtig ergänzt."},"hint":{"en":"She is learning German in addition to her first language.","de":"Sie lernt Deutsch zusätzlich zu ihrer Erstsprache."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"Muttersprache"},{"id":"1","text":"Geheimsprache"},{"id":"2","text":"Zweitsprache"},{"id":"3","text":"Fachsprache"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"2"}]}],"explanation":{"en":"German is her Zweitsprache in this context.","de":"Deutsch ist in diesem Kontext ihre Zweitsprache."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Nach dem Umzug nach Deutschland lernt Elena im Alltag Deutsch neben ihrer Erstsprache. Deutsch ist ihre Zweitsprache.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L2804 (df6f6e9d1d2f9d1b0c22f683eece964734971fd03a3513acb520d3b4e28d066f), 2026-10-29; inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
