INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001750141','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001750141","revision":1,"targetId":"80000000-0000-4000-8000-000000017514","prompt":"Ein Kind spricht zu Hause Türkisch und erwirbt in einer deutschsprachigen Schule Deutsch als weitere Alltagssprache. Wie nennt man Deutsch hier?","instruction":{"en":"Read the German situation and choose the single correct answer.","de":"Lies die deutsche Situation und wähle die einzige richtige Antwort."},"hint":{"en":"It is another language used in the child''s surroundings.","de":"Es ist eine weitere Sprache im Alltag des Kindes."},"options":[{"id":"0","text":"Erstsprache"},{"id":"1","text":"Zweitsprache"},{"id":"2","text":"Dialekt"},{"id":"3","text":"Kunstsprache"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"German is the child''s Zweitsprache in this situation.","de":"Deutsch ist in dieser Situation die Zweitsprache des Kindes."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Deutsch ist die Zweitsprache.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L2804 (df6f6e9d1d2f9d1b0c22f683eece964734971fd03a3513acb520d3b4e28d066f), 2026-10-29; inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
