INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001750151','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001750151","revision":1,"targetId":"80000000-0000-4000-8000-000000017515","prompt":"Beim Schneiden welcher Zutat können reizende Stoffe die Augen zum Tränen bringen?","instruction":{"en":"Read the German situation and choose the single correct answer.","de":"Lies die deutsche Situation und wähle die einzige richtige Antwort."},"hint":{"en":"Think of the vegetable that often makes people cry when cut.","de":"Denk an das Gemüse, das beim Schneiden häufig Tränen auslöst."},"options":[{"id":"0","text":"Kartoffel"},{"id":"1","text":"Zwiebel"},{"id":"2","text":"Gurke"},{"id":"3","text":"Karotte"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"Cutting an onion can release irritating compounds that make eyes water.","de":"Beim Schneiden einer Zwiebel können reizende Stoffe Tränen auslösen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Das ist die Zwiebel.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L2805 (74d4af17416b7b1af42a9470b8d34c99fbeb6147c8a1c32aff863c9f93ade57d), 2026-10-29; inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
